<script setup lang="ts">
import { computed, onScopeDispose, reactive, ref, watch } from 'vue'
import { ElMessageBox } from 'element-plus'
import { api, errorText, formatTime } from '../api'
import type { EvidenceRef } from '../information-types'
import EditDialog from './EditDialog.vue'
import EditorWorkspace from './EditorWorkspace.vue'
import SplitPane from './SplitPane.vue'
import EvidencePicker from './EvidencePicker.vue'
import EvidenceSources from './EvidenceSources.vue'
const props = defineProps<{ instanceId: string; timezone: string; refreshKey: number }>()
interface Policy { revision: number; schedules_enabled: boolean; events_enabled: boolean; observations_enabled: boolean; timezone: string; max_events: number; event_daily_cap: number; observation_daily_cap: number; observation_sources: { id: string; name: string; url: string }[] }
interface Entry { id: string; kind: 'fixed' | 'routine' | 'flexible' | 'exception'; title: string; starts_at: number | null; ends_at: number | null; weekdays: number[]; local_start: string; local_end: string; exception_date: string | null; replaces_id: string | null; cancelled: boolean; sources: EvidenceRef[] }
interface EventRow { id: number; revision: number; status: string; config_json: string; due_at: number; expires_at: number; intent_id: string | null }
interface Observation { id: number; source_id: string; source_url: string; purpose: string; status: string; due_at: number; expires_at: number; acquired_at: number | null; text: string | null; truncated: boolean; error: string | null }
interface Data { policy: Policy; schedule: { entries: Entry[]; revision: number; intent_id: string | null; occurrences: { id: string; title: string; starts_at: number; ends_at: number; status: string }[]; conflicts: string[][]; occurrences_limited?: boolean }; events: EventRow[]; observations: Observation[] }
const data = ref<Data | null>(null), error = ref(''), editError = ref(''), busy = ref(false), loading = ref(false), changed = ref(false), tab = ref('schedule')
const settingOpen = ref(false), scheduleOpen = ref(false), draftOpen = ref(false), sourceOpen = ref(false)
const settingDialog = ref<InstanceType<typeof EditDialog> | null>(null), draftDialog = ref<InstanceType<typeof EditDialog> | null>(null), scheduleEditor = ref<InstanceType<typeof EditorWorkspace> | null>(null)
const settings = ref<Policy | null>(null), plan = reactive({ revision: 0, entries: [] as Entry[] }), selected = ref(0), editorInstance = ref('')
const current = computed(() => plan.entries[selected.value]), selectedSources = computed({ get: () => current.value?.sources ?? [], set: value => { if (current.value) current.value.sources = value } })
const start = computed({ get: () => current.value?.starts_at ? current.value.starts_at * 1000 : null, set: value => { if (current.value) current.value.starts_at = value ? Number(value) / 1000 : null } })
const end = computed({ get: () => current.value?.ends_at ? current.value.ends_at * 1000 : null, set: value => { if (current.value) current.value.ends_at = value ? Number(value) / 1000 : null } })
const kinds = { fixed: '固定安排', routine: '日常习惯', flexible: '弹性事项', exception: '日期例外' }
const statusNames: Record<string, string> = { pending: '待评估', adopted: '已采纳', discarded: '已丢弃', expired: '已过期', fetching: '获取中', observed: '已取得', obsolete: '已失效', failed: '失败', unknown: '结果未知', cancelled: '已取消' }
const draftKind = ref<'event' | 'observation'>('event'), draft = reactive({ summary: '', rationale: '', source_id: '', purpose: '', due: null as number | null, expires: null as number | null })
const detail = ref<Observation | null>(null), detailOpen = ref(false)
let version = 0, disposed = false
async function load() {
  const mine = ++version; loading.value = true
  try { const value = await api<Data>(`/roleplay/life/instances/${props.instanceId}/materials`); if (mine === version) { data.value = value; error.value = ''; changed.value = false } }
  catch (cause) { if (mine === version) error.value = errorText(cause) }
  finally { if (mine === version) loading.value = false }
}
function openSettings() { if (!data.value) return; editorInstance.value = props.instanceId; settings.value = structuredClone(data.value.policy); editError.value = ''; settingOpen.value = true }
function addSource() { settings.value?.observation_sources.push({ id: crypto.randomUUID(), name: '', url: '' }) }
function openSchedule() { if (!data.value) return; editorInstance.value = props.instanceId; Object.assign(plan, { revision: data.value.schedule.revision, entries: structuredClone(data.value.schedule.entries) }); selected.value = 0; editError.value = ''; scheduleOpen.value = true }
function addEntry() { plan.entries.push({ id: crypto.randomUUID(), kind: 'fixed', title: '', starts_at: null, ends_at: null, weekdays: [], local_start: '09:00', local_end: '10:00', exception_date: null, replaces_id: null, cancelled: false, sources: [] }); selected.value = plan.entries.length - 1 }
async function save(path: string, body: unknown, close: () => void) {
  if (busy.value) return
  const target = editorInstance.value; busy.value = true; editError.value = ''
  try { await api(`/roleplay/life/instances/${target}/materials/${path}`, { method: 'PUT', body: JSON.stringify(body) }); close(); if (!disposed && props.instanceId === target) await load() }
  catch (cause) { editError.value = errorText(cause) }
  finally { busy.value = false }
}
function saveSchedule() {
  const entries = plan.entries.map(item => ({ ...item, starts_at: item.kind === 'routine' ? null : item.starts_at, ends_at: item.kind === 'routine' ? null : item.ends_at, exception_date: item.kind === 'exception' ? item.exception_date : null, replaces_id: item.kind === 'exception' ? item.replaces_id : null, cancelled: item.kind === 'exception' && item.cancelled }))
  void save('schedule', { revision: plan.revision, entries }, () => { scheduleOpen.value = false })
}
function openDraft(kind: 'event' | 'observation') { editorInstance.value = props.instanceId; draftKind.value = kind; Object.assign(draft, { summary: '', rationale: '', purpose: '', source_id: data.value?.policy.observation_sources[0]?.id ?? '', due: Date.now() + 300000, expires: Date.now() + 3600000 }); editError.value = ''; draftOpen.value = true }
async function createDraft() {
  if (busy.value) return
  const target = editorInstance.value; busy.value = true; editError.value = ''
  const body = { due_at: Number(draft.due) / 1000, expires_at: Number(draft.expires) / 1000, ...(draftKind.value === 'event' ? { summary: draft.summary, rationale: draft.rationale, sources: [] } : { source_id: draft.source_id, purpose: draft.purpose }) }
  try { await api(`/roleplay/life/instances/${target}/materials/${draftKind.value === 'event' ? 'events' : 'observations'}`, { method: 'POST', body: JSON.stringify(body) }); draftOpen.value = false; if (!disposed && props.instanceId === target) await load() }
  catch (cause) { editError.value = errorText(cause) }
  finally { busy.value = false }
}
async function cancel(kind: string, id: number, revision?: number) {
  if (busy.value) return
  const target = props.instanceId; busy.value = true
  try {
    try { await ElMessageBox.confirm('取消此候选或请求，已取得资料和历史记录保留。', '取消计划', { confirmButtonText: '确认取消', cancelButtonText: '返回' }) } catch { return }
    if (disposed || target !== props.instanceId) return
    await api(`/roleplay/life/instances/${target}/materials/${kind}/${id}/cancel`, { method: 'POST', body: JSON.stringify({ revision: revision ?? null }) })
    if (!disposed && target === props.instanceId) await load()
  } catch (cause) { if (!disposed) error.value = errorText(cause) }
  finally { busy.value = false }
}
const eventDraft = (row: EventRow) => JSON.parse(row.config_json) as { summary: string; rationale: string; sources: EvidenceRef[] }
watch(() => props.instanceId, () => { data.value = null; void load() }, { immediate: true })
watch(() => props.refreshKey, () => { changed.value = true })
onScopeDispose(() => { version++; disposed = true })
</script>

<template>
  <el-alert v-if="error" :title="error" type="error" :closable="false" class="form-alert" />
  <div class="section-toolbar"><el-tabs v-model="tab"><el-tab-pane label="近期日程" name="schedule" /><el-tab-pane label="事件候选" name="events" /><el-tab-pane label="公开观察" name="observations" /></el-tabs><div><el-button :loading="loading" :disabled="busy" @click="load()">{{ changed ? '有变化 · 刷新' : '刷新' }}</el-button><el-button :disabled="!data || busy" @click="openSettings">设置</el-button></div></div>
  <template v-if="data">
    <section v-if="tab === 'schedule'" class="panel"><div class="section-toolbar"><el-tag effect="plain">{{ data.policy.schedules_enabled ? '日程已启用' : '日程未启用' }}</el-tag><el-button :disabled="busy" @click="openSchedule">编辑日程</el-button></div><el-alert v-if="data.schedule.conflicts.length" title="存在时间重叠，请在编辑中调整或交由角色判断。" type="warning" :closable="false" class="form-alert" /><el-table :data="data.schedule.occurrences" empty-text="未来八天暂无有效安排"><el-table-column prop="title" label="预期安排" /><el-table-column label="开始" min-width="180"><template #default="{ row }">{{ formatTime(row.starts_at, data.policy.timezone) }}</template></el-table-column><el-table-column label="结束" min-width="180"><template #default="{ row }">{{ formatTime(row.ends_at, data.policy.timezone) }}</template></el-table-column><el-table-column label="状态"><template #default="{ row }">{{ row.status === 'expected_now' ? '此时预计进行' : '计划中' }}</template></el-table-column></el-table><el-tag v-if="data.schedule.occurrences_limited" effect="plain">仅展示前 64 项，可在编辑中查看完整日程</el-tag></section>
    <section v-else-if="tab === 'events'" class="panel"><div class="section-toolbar"><el-tag effect="plain">{{ data.policy.events_enabled ? '候选已启用' : '候选未启用' }}</el-tag><el-button :disabled="busy || !data.policy.events_enabled" @click="openDraft('event')">添加候选</el-button></div><el-empty v-if="!data.events.length" description="暂无事件候选" /><article v-for="row in data.events" :key="row.id" class="check-record"><div class="section-toolbar"><strong>#{{ row.id }} · {{ eventDraft(row).summary }}</strong><div><el-tag effect="plain">{{ statusNames[row.status] || row.status }}</el-tag><el-button v-if="row.status === 'pending'" link :disabled="busy" @click="cancel('event', row.id, row.revision)">丢弃</el-button></div></div><p>{{ eventDraft(row).rationale }}</p><div class="check-metadata"><span>评估 {{ formatTime(row.due_at, timezone) }}</span><span>失效 {{ formatTime(row.expires_at, timezone) }}</span><span v-if="row.status === 'pending' && !row.intent_id">等待正常生活轮评估</span></div><EvidenceSources :instance-id="instanceId" :sources="eventDraft(row).sources" :timezone="timezone" /></article></section>
    <section v-else class="panel"><div class="section-toolbar"><el-tag effect="plain">{{ data.policy.observations_enabled ? '观察已启用' : '观察未启用' }}</el-tag><el-button :disabled="busy || !data.policy.observations_enabled || !data.policy.observation_sources.length" @click="openDraft('observation')">安排观察</el-button></div><el-table :data="data.observations" empty-text="暂无观察记录"><el-table-column prop="purpose" label="目的" min-width="160" /><el-table-column label="状态" width="110"><template #default="{ row }">{{ statusNames[row.status] || row.status }}</template></el-table-column><el-table-column label="安排时间" min-width="180"><template #default="{ row }">{{ formatTime(row.due_at, timezone) }}</template></el-table-column><el-table-column label="操作" width="140"><template #default="{ row }"><el-button link @click="detail = row; detailOpen = true">详情</el-button><el-button v-if="row.status === 'pending'" link :disabled="busy" @click="cancel('observation', row.id)">取消</el-button></template></el-table-column></el-table></section>
  </template>
  <EditDialog ref="settingDialog" v-model="settingOpen" :draft="settings" :busy="busy" title="生活资料设置" width="760px"><el-alert v-if="editError" :title="editError" type="error" :closable="false" class="form-alert" /><el-form v-if="settings" label-position="top" @submit.prevent="save('policy', settings, () => { settingOpen = false })"><div class="section-toolbar"><el-switch v-model="settings.schedules_enabled" active-text="近期日程" /><el-switch v-model="settings.events_enabled" active-text="世界事件候选" /><el-switch v-model="settings.observations_enabled" active-text="公开观察" /></div><el-form-item label="日程时区"><el-input v-model="settings.timezone" maxlength="80" /></el-form-item><el-collapse class="quiet-collapse"><el-collapse-item title="数量限制" name="limits"><div class="form-two-columns"><el-form-item label="同时保留事件候选"><el-input-number v-model="settings.max_events" :min="1" :max="16" /></el-form-item><el-form-item label="24 小时事件候选上限"><el-input-number v-model="settings.event_daily_cap" :min="1" :max="24" /></el-form-item><el-form-item label="24 小时公开观察上限"><el-input-number v-model="settings.observation_daily_cap" :min="1" :max="24" /></el-form-item></div></el-collapse-item></el-collapse><div class="section-toolbar"><strong>允许的公开来源</strong><el-button :disabled="settings.observation_sources.length >= 8" @click="addSource()">添加来源</el-button></div><article v-for="(source, index) in settings.observation_sources" :key="source.id" class="check-record"><div class="section-toolbar"><el-input v-model="source.name" placeholder="来源名称" maxlength="100" /><el-button link type="danger" @click="settings!.observation_sources.splice(index, 1)">移除</el-button></div><el-input v-model="source.url" placeholder="https://公开页面地址" maxlength="2000" /></article><div class="form-actions"><el-button @click="settingDialog?.close()">取消</el-button><el-button type="primary" native-type="submit" :loading="busy">保存设置</el-button></div></el-form></EditDialog>
  <EditorWorkspace ref="scheduleEditor" v-model="scheduleOpen" title="编辑近期日程" :draft="plan" :busy="busy" :version="plan.revision"><el-alert v-if="editError" :title="editError" type="error" :closable="false" class="form-alert" /><el-form label-position="top" :disabled="busy" @submit.prevent="saveSchedule"><SplitPane label="调整日程列表宽度" :selection="selected" detail-label="日程安排"><template #list="{ open: openDetail }"><div class="section-toolbar"><strong>{{ plan.entries.length }} 项</strong><el-button :disabled="plan.entries.length >= 64" @click="addEntry(); openDetail()">添加</el-button></div><div class="editor-list"><button v-for="(item, index) in plan.entries" :key="item.id" type="button" :class="['editor-list-item', { active: index === selected }]" @click="selected = index; openDetail()"><strong>{{ item.title || '新安排' }}</strong><span>{{ kinds[item.kind] }}</span></button></div></template><template v-if="current"><div class="section-toolbar"><el-select v-model="current.kind"><el-option v-for="(label, key) in kinds" :key="key" :value="key" :label="label" /></el-select><el-button link type="danger" @click="plan.entries.splice(selected, 1); selected = Math.max(0, selected - 1)">移除</el-button></div><el-form-item label="名称"><el-input v-model="current.title" maxlength="200" /></el-form-item><template v-if="current.kind === 'routine'"><el-form-item label="星期"><el-checkbox-group v-model="current.weekdays"><el-checkbox v-for="(day, index) in ['一','二','三','四','五','六','日']" :key="day" :value="index">周{{ day }}</el-checkbox></el-checkbox-group></el-form-item><div class="form-two-columns"><el-form-item label="本地开始"><el-time-select v-model="current.local_start" start="00:00" end="23:59" step="00:15" /></el-form-item><el-form-item label="本地结束"><el-time-select v-model="current.local_end" start="00:00" end="23:59" step="00:15" /></el-form-item></div></template><template v-else><template v-if="current.kind === 'exception'"><el-form-item label="原安排"><el-select v-model="current.replaces_id"><el-option v-for="item in plan.entries.filter(item => item.kind !== 'exception')" :key="item.id" :value="item.id" :label="item.title || item.id" /></el-select></el-form-item><el-form-item label="例外日期（日程时区）"><el-date-picker v-model="current.exception_date" type="date" value-format="YYYY-MM-DD" /></el-form-item><el-switch v-model="current.cancelled" active-text="当天取消" /></template><div v-if="!current.cancelled" class="form-two-columns"><el-form-item label="开始（本机时区）"><el-date-picker v-model="start" type="datetime" value-format="x" /></el-form-item><el-form-item label="结束（本机时区）"><el-date-picker v-model="end" type="datetime" value-format="x" /></el-form-item></div></template><el-form-item label="依据"><el-button @click="sourceOpen = true">选择来源</el-button><EvidenceSources :instance-id="editorInstance" :sources="current.sources" :timezone="timezone" /><el-button v-if="current.sources.length" link @click="current.sources = []">清空选择</el-button></el-form-item></template><el-empty v-else description="添加一项安排" /></SplitPane><div class="form-actions"><el-button @click="scheduleEditor?.close()">取消</el-button><el-button type="primary" native-type="submit" :loading="busy">保存日程</el-button></div></el-form></EditorWorkspace>
  <EditDialog ref="draftDialog" v-model="draftOpen" :draft="draft" :busy="busy" :title="draftKind === 'event' ? '添加世界事件候选' : '安排公开观察'" width="650px"><el-alert v-if="editError" :title="editError" type="error" :closable="false" class="form-alert" /><el-form label-position="top" @submit.prevent="createDraft"><template v-if="draftKind === 'event'"><el-form-item label="可能发生的事件"><el-input v-model="draft.summary" type="textarea" :rows="4" maxlength="1000" /></el-form-item><el-form-item label="候选理由"><el-input v-model="draft.rationale" maxlength="500" /></el-form-item></template><template v-else><el-form-item label="公开来源"><el-select v-model="draft.source_id"><el-option v-for="source in data?.policy.observation_sources" :key="source.id" :value="source.id" :label="source.name" /></el-select></el-form-item><el-form-item label="观察目的"><el-input v-model="draft.purpose" maxlength="500" /></el-form-item></template><div class="form-two-columns"><el-form-item label="评估／获取时间（本机时区）"><el-date-picker v-model="draft.due" type="datetime" value-format="x" /></el-form-item><el-form-item label="失效时间（本机时区）"><el-date-picker v-model="draft.expires" type="datetime" value-format="x" /></el-form-item></div><div class="form-actions"><el-button @click="draftDialog?.close()">取消</el-button><el-button type="primary" native-type="submit" :loading="busy">保存计划</el-button></div></el-form></EditDialog>
  <el-drawer v-model="detailOpen" title="公开观察" size="min(760px, 94vw)" class="detail-drawer"><template v-if="detail"><p>{{ detail.purpose }}</p><p class="message-text">{{ detail.source_url }}</p><p>{{ statusNames[detail.status] }} · {{ formatTime(detail.acquired_at, timezone) }}</p><el-alert v-if="detail.error" :title="detail.error" type="warning" :closable="false" /><p class="message-text">{{ detail.text }}</p><el-tag v-if="detail.truncated">正文为截取</el-tag></template></el-drawer>
  <EvidencePicker v-model="sourceOpen" v-model:selection="selectedSources" :instance-id="editorInstance" :timezone="timezone" />
</template>
